do $do$
declare run_id bigint; rid bigint; a bigint; b bigint; r record; k int; isnew boolean;
begin
insert into public.companies(ticker,name,segment,size_tier,is_seed,is_hero,markets,exchange,country) values ($q$CCC$q$,$q$Computacenter$q$,null,null,true,false,array[$q$LSE$q$]::text[],null,$q$GB$q$) on conflict (ticker) do update set is_seed=true, segment=excluded.segment, size_tier=excluded.size_tier, is_hero=excluded.is_hero, markets=case when cardinality(excluded.markets)>0 then excluded.markets else public.companies.markets end, exchange=coalesce(excluded.exchange, public.companies.exchange), country=coalesce(excluded.country, public.companies.country);
insert into public.companies(name,entity_type) select v.n,v.t from (values ($q$AgreeYa Solutions$q$,$q$private_company$q$),($q$BT$q$,$q$public_company$q$),($q$Business IT Source Holdings, Inc (BITS)$q$,$q$private_company$q$),($q$FusionStorm$q$,$q$private_company$q$),($q$Genesys$q$,$q$private_company$q$),($q$HP$q$,$q$public_company$q$),($q$Microsoft$q$,$q$public_company$q$),($q$ProSys Information Systems$q$,$q$private_company$q$),($q$SAP$q$,$q$public_company$q$),($q$Salesforce$q$,$q$public_company$q$),($q$ServiceNow$q$,$q$public_company$q$),($q$The Hadley Trust$q$,$q$organization$q$)) v(n,t) where not exists (select 1 from public.companies c where lower(c.name)=lower(v.n));
create temp table _q(i int primary key, t text) on commit drop;
insert into _q values (1,$q$After the year end, we approved the acquisition of AgreeYa Solutions Inc. in North America, having spent considerable time during 2025 reviewing the transaction.$q$),(2,$q$At the start of 2026 we were pleased to complete the acquisition of AgreeYa, a focused Professional Services business, for US$120m, and we welcome our new colleagues in North America and India to the Group.$q$),(3,$q$He joined the Company in 2007 through Computacenter’s acquisition of FusionStorm and has served as the Senior Vice President of Sales for the US since 2018.$q$),(4,$q$In 2024, the Group completed the final contingent consideration payments for the purchase of Business IT Source Holdings, Inc (BITS).$q$),(5,$q$Increasing the volume of business with the private sector, to bring greater balance to our customer portfolio, while at the same time reducing legacy costs associated with the acquisition of BT Services, are key priorities for 2026 and beyond.$q$),(6,$q$On 29 August 2025, the Group acquired the non-controlling interest in ProSys for a cash consideration of $0.1 m and a deferred consideration of $1.8m, which was paid on 2 January 2026.$q$),(7,$q$On 5 January 2026, the Group acquired 100% of the voting shares of AgreeYa Solutions Inc., a Professional Services business focused on the US enterprise market, and the assets of the associated business, AgreeYa India, for an enterprise value of up to $120m.$q$),(8,$q$The Hadley Trust 7.09% Philip Willam Hulme 7.93%$q$),(9,$q$We continue to invest in improving our platforms to provide improved customer service, efficiency and innovation, including Artificial Intelligence (AI), using technology from among the world’s leading providers, including Microsoft, SAP, ServiceNow and Salesforce.$q$),(10,$q$We received continued recognition from value chain partners, including HP’s Amplify Impact 5-Star award and the Genesys Sustainability Award, and we strengthened our collaboration with customers to help them achieve their own sustainability goals.$q$),(11,$q$we have better visibility of the business through reporting insights and through deployment of automation tooling such as Genesys, helping us to deliver better service to Customers while reducing cost.$q$),(12,$q$£2.2m relating to a release of contingent consideration in relation to the Business IT Source Holdings, Inc (BITS) acquisition, net of £0.4m of costs incurred as per the share purchase agreement.$q$);
create temp table _e(n int, ty text, s text, g text, qs int[], sec text[], pct numeric, qual text, basis text, note text) on commit drop;
insert into _e values (1,$q$acquires$q$,$q$CCC$q$,$q$AgreeYa Solutions$q$,$q${2,1,7}$q$::int[],$q${p22,p80,p212}$q$::text[],null,null,null,null),(2,$q$acquires$q$,$q$CCC$q$,$q$BT$q$,$q${5}$q$::int[],$q${p22}$q$::text[],null,null,null,null),(3,$q$supplies$q$,$q$Microsoft$q$,$q$CCC$q$,$q${9}$q$::int[],$q${p12}$q$::text[],null,null,null,null),(4,$q$supplies$q$,$q$SAP$q$,$q$CCC$q$,$q${9}$q$::int[],$q${p12}$q$::text[],null,null,null,null),(5,$q$supplies$q$,$q$ServiceNow$q$,$q$CCC$q$,$q${9}$q$::int[],$q${p12}$q$::text[],null,null,null,null),(6,$q$supplies$q$,$q$Salesforce$q$,$q$CCC$q$,$q${9}$q$::int[],$q${p12}$q$::text[],null,null,null,null),(7,$q$acquires$q$,$q$CCC$q$,$q$Business IT Source Holdings, Inc (BITS)$q$,$q${4,12}$q$::int[],$q${p35,p177}$q$::text[],null,null,null,null),(8,$q$partners$q$,$q$CCC$q$,$q$HP$q$,$q${10}$q$::int[],$q${p53}$q$::text[],null,null,null,null),(9,$q$partners$q$,$q$CCC$q$,$q$Genesys$q$,$q${10}$q$::int[],$q${p53}$q$::text[],null,null,null,null),(10,$q$acquires$q$,$q$CCC$q$,$q$FusionStorm$q$,$q${3}$q$::int[],$q${p95}$q$::text[],null,null,null,null),(11,$q$invests$q$,$q$The Hadley Trust$q$,$q$CCC$q$,$q${8}$q$::int[],$q${p139}$q$::text[],7.09,$q$exact$q$,$q$ownership$q$,null),(12,$q$supplies$q$,$q$Genesys$q$,$q$CCC$q$,$q${11}$q$::int[],$q${p126}$q$::text[],null,null,null,null),(13,$q$acquires$q$,$q$CCC$q$,$q$ProSys Information Systems$q$,$q${6}$q$::int[],$q${p189}$q$::text[],null,null,null,null);
create or replace function pg_temp.nid(l text) returns bigint language sql as $f$ select id from public.companies where case l when $q$CCC$q$ then ticker=$q$CCC$q$ else lower(name)=lower(l) end order by id limit 1 $f$;
insert into public.agent_runs(agent_name,mode,target,model,cost_usd,status,review_status) values ('filings_extraction','batch',$q$CCC Computacenter annual report 2025 (M14)$q$,'claude-sonnet-5-5 via Claude Code session',1.2797,'completed','unreviewed') returning id into run_id;
for r in select * from _e order by n loop a := pg_temp.nid(r.s); b := pg_temp.nid(r.g); if r.ty in ('competes','partners') and a > b then rid := a; a := b; b := rid; end if; isnew := false; rid := null; select id into rid from public.relationships where source_id=a and target_id=b and relationship_type=r.ty order by id limit 1; if rid is null then insert into public.relationships(source_id,target_id,relationship_type,exposure_pct,exposure_qualifier,exposure_basis,exposure_as_of,source_type,status,trust_status,run_id,as_of_date,note) values (a,b,r.ty,r.pct,r.qual,case when r.pct is null then 'none' else r.basis end,case when r.pct is null then null else $q$2025-12-31$q$::date end,$q$annual_report$q$,$q$staged$q$,null,run_id,$q$2025-12-31$q$::date,r.note) returning id into rid; isnew := true; end if; if isnew then for k in 1..array_length(r.qs,1) loop insert into public.evidence(relationship_id,document_url,section,quote,quote_found,published_at) select rid,null,r.sec[k],t,true,null from _q where i=r.qs[k]; end loop; end if; end loop;
end $do$;
